]$edition$::jsonb) AS e(
  "catalogKey" text, "catalogVersion" integer, name text, category text, tags text[],
  aliases text[], cues text[], prescription jsonb, classification jsonb, "strengthLoadKind" text, guide jsonb
);

INSERT INTO platform_settings (key, value, updated_at)
SELECT format('exerciseReview:%s:v%s:%s:v%s', e."catalogKey", e."catalogVersion", d.kind, d.version),
       'true'::jsonb, CURRENT_TIMESTAMP
FROM reviewed_guides e
CROSS JOIN LATERAL (VALUES ('text', e."catalogVersion"), ('motion', 2)) AS d(kind, version)
ON CONFLICT (key) DO NOTHING;

-- Une décision plus récente de l'atelier reste prioritaire. Les fiches de stade
-- ne sont ajoutées qu'après les trois validations de la version correspondante.
INSERT INTO exercises (id, catalog_key, catalog_version, name, category, tags, aliases, cues,
                      default_prescription, classification, strength_load_kind, guide, updated_at)
SELECT gen_random_uuid(), e."catalogKey", e."catalogVersion", e.name, e.category::exercise_category,
       e.tags, e.aliases, e.cues, e.prescription, e.classification, e."strengthLoadKind",
       jsonb_set(e.guide, '{technicalReview}', '"approved"'), CURRENT_TIMESTAMP
FROM reviewed_guides e
WHERE NOT EXISTS (
  SELECT 1 FROM (VALUES ('text', e."catalogVersion"), ('motion', 2), ('image', 1)) AS d(kind, version)
  WHERE NOT EXISTS (
    SELECT 1 FROM platform_settings p
    WHERE p.key = format('exerciseReview:%s:v%s:%s:v%s', e."catalogKey", e."catalogVersion", d.kind, d.version)
      AND p.value = 'true'::jsonb
  )
)
ON CONFLICT (catalog_key) DO NOTHING;

-- Ne modifier que le statut du texte canonique d'une fiche commune active.
-- Une copie privée, une autre édition ou un guide réécrit garde son contenu.
UPDATE exercises x
SET guide = jsonb_set(x.guide, '{technicalReview}', '"approved"'), updated_at = CURRENT_TIMESTAMP
FROM reviewed_guides e
WHERE x.organization_id IS NULL AND x.deleted_at IS NULL
  AND x.catalog_key = e."catalogKey" AND x.catalog_version = e."catalogVersion"
  AND x.guide->>'technicalReview' = 'pending'
  AND x.guide - 'technicalReview' = e.guide - 'technicalReview'
  AND EXISTS (
    SELECT 1 FROM platform_settings p
    WHERE p.key = format('exerciseReview:%s:v%s:text:v%s', e."catalogKey", e."catalogVersion", e."catalogVersion")
      AND p.value = 'true'::jsonb
  );
COMMIT;
